   en: "The final destination of the life-source:",
     
  bn: "জীবন-উৎসটির চূড়ান্ত গন্তব্য:",

  hi: "जीवन-स्रोत की आखिरी मंज़िल: ",

  sa: "प्राणस्रोतस्य अन्तिमगन्तव्यं :",
