    hi: "जीवन के अनुभव और शरीर का पुनर्गठन, मन की अनुभूतियों तथा चेतना की अनुभूति से अलग-अलग सत्ताएँ नहीं हैं, बल्कि जीवन की संवेदनशीलता के उसी प्रवाह की बहुआयामी अभिव्यक्तियाँ हैं; यहाँ शून्यता जीवन-अनुभवों और नवीन सृजन की संभावनाओं का क्षेत्र बन जाती है; विविध मुखाकृतियाँ और प्रतीकात्मक विन्यास जीवन के परिवर्तनशील अनुभवों को धारण करते हैं, जो अनुशासन की सहज अनुभूति का संकेत हैं; यह चित्र अस्तित्व की गहराई में देह-मन के परिष्कार, आत्म-अन्वेषण और त्रिविध सत्ता की एकता की अनुभूति का मार्ग खोलता है;",

    sa: "देहस्य पुनर्निर्माणं च मनसः अनुभूतिभ्यः चेतसः प्रत्यभिज्ञानाच्च पृथक् सत्ताः न, अपितु जीवनस्य संवेदनशीलतायाः एकस्यैव प्रवाहस्य बहुआयामात्मकाः अभिव्यक्तयः सन्ति; अत्र शून्यता जीवनानुभवानां नूतनसृष्टेः सम्भावनानां च क्षेत्रं भवति; विविधाः मुखाकृतयः प्रतीकात्मकविन्यासाश्च जीवनस्य परिवर्तनशीलान् अनुभवाञ् धारयन्ति, ये व्यवस्थायाः सहजं बोधं सूचयन्ति; एतत् चित्रम् अस्तित्वस्य गभीरतायां देह-मनसोः परिष्कारस्य, आत्मान्वेषणस्य, त्रिविधसत्तायाः ऐक्यबोधस्य च मार्गम् उद्घाटयति;",
