    en: "Primordial Yogi points towards the realization of nature’s deeper truths through meditation, self-restraint and inner vision; the symbolic arrangement of the Sun, Moon and Earth represents the mutual balance of life’s origin, creation and energy; here, the Primordial Yogi’s austerity and yogic practice are not merely personal disciplines, but an inward process of seeking unity among life, nature and culture; through spiritual realization, the painting reflects the primordial source and eternal continuity of the threefold dimensions of life;",

    hi: "माध्यम से प्रकृति के गहन सत्य की अनुभूति का संकेत देती है; सूर्य, चंद्र और पृथ्वी का प्रतीकात्मक विन्यास जीवन के गर्भ, सृष्टि और शक्ति के पारस्परिक संतुलन को दर्शाता है; यहाँ आदियोगी की तपस्या और योगसाधना केवल व्यक्तिगत अभ्यास नहीं, बल्कि जीवन, प्रकृति और संस्कृति के बीच एकता की खोज की अंतर्मुखी प्रक्रिया है; यह चित्र आध्यात्मिक अनुभूति के माध्यम से जीवन के त्रिविध आयामों के आदि स्रोत और शाश्वत निरंतरता को प्रतिबिंबित करता है;",

    sa: "माध्यमेन प्रकृतेः गहनसत्यस्य अनुभूतिं सूचयति; सूर्यचन्द्रपृथिवीनां प्रतीकात्मकः विन्यासः जीवनगर्भस्य, सृष्टेः, शक्तेः च पारस्परिकं सन्तुलनं दर्शयति; अत्र आदियोगिनः तपस्या योगसाधना च केवलं व्यक्तिगतः अभ्यासः न, अपितु जीवन-प्रकृति-संस्कृतीनां मध्ये ऐक्यान्वेषणस्य अन्तर्मुखी प्रक्रिया अस्ति; आध्यात्मिकानुभूतेः माध्यमेन एतत् चित्रं जीवनस्य त्रिविधायामानाम् आदिमं स्रोतः शाश्वतीं निरन्तरतां च प्रतिबिम्बयति;",
