  hi: "पूर्व अनुभवों की निरंतरता में एक नई सत्ता का विकास करता है, जहाँ पुनर्जन्म केवल शरीर का परिवर्तन नहीं, बल्कि आत्मबोध की एक अंतर्मुखी प्रक्रिया है; बोधिसत्त्व की प्रतिबिंबित आकृति परम सत्ता के साथ आंतरिक संबंध का प्रतीक है; चित्र के उज्ज्वल रंग, विभाजित पृष्ठभूमि और स्थिर आकृतियाँ आत्मजागरण, प्रत्यावर्तन तथा चेतना की पूर्णता की ओर यात्रा को दर्शाती हैं;",

  sa: "नूतनायाः सत्तायाः विकासं जनयति, यत्र पुनर्जन्म केवलं शरीरस्य परिवर्तनं न, अपितु आत्मबोधस्य अन्तर्मुखी प्रक्रिया अस्ति; बोधिसत्त्वस्य प्रतिबिम्बिता आकृतिः परमसत्तया सह आन्तरिकसम्बन्धस्य प्रतीकम् अस्ति; चित्रस्य उज्ज्वलवर्णाः, विभक्तपृष्ठभूमिः, स्थिराकृतयश्च आत्मजागरणस्य, प्रत्यावर्तनस्य, चेतनायाः पूर्णतायाश्च दिशि यात्रां प्रकाशयन्ति;"
