  en: "symbolic arrangement of numbers; the number 0 represents the foundation of emptiness and possibility, while the reflected number 8 suggests continuity, recurrence, and an infinite flow; the diagonal symbolic forms of addition and multiplication (+ / ×) convey the connection between the life cycles of distinct entities and the idea of collective expansion; the central form of the painting, through its layers of geometric divisions, indicates an uninterrupted cycle of life, from emptiness to wholeness and from wholeness to new creation;",

  hi: "संभावनाओं का आधार है, जबकि प्रतिबिंबित संख्या ८ निरंतरता, पुनरावर्तन और अनंत प्रवाह का संकेत देती है; जोड़ और गुणा (+ / ×) के तिरछे प्रतीकात्मक रूप अलग-अलग सत्ताओं के जीवनचक्रों के संबंध और सामूहिक विस्तार की अवधारणा को प्रस्तुत करते हैं; चित्र की केंद्रीय सत्ता ज्यामितीय विभाजनों की विभिन्न परतों के माध्यम से शून्यता से पूर्णता और पूर्णता से नई सृष्टि तक के अविच्छिन्न जीवनचक्र को दर्शाती है;",

  sa: "आधारः, प्रतिबिम्बितः अष्टाङ्कः सातत्यस्य पुनरावर्तनस्य अनन्तप्रवाहस्य च सूचकः; योगस्य गुणनस्य च (+ / ×) तिर्यक्प्रतीकात्मकानि रूपाणि विभिन्नसत्तानां जीवनचक्रयोः सम्बन्धं सामूहिकविस्तारस्य च भावनां प्रकाशयन्ति; चित्रस्य केन्द्रीयं तत्त्वं ज्यामितीयविभाजनानां विभिन्नस्तरैः शून्यतायाः पूर्णतां प्रति, पूर्णतायाः नूतनसृष्टिं प्रति च अविच्छिन्नं जीवनचक्रं निर्दिशति;"
