descFull: {
  bn: "গঠন এবং সৃষ্টির বীজ থেকে শুরু করে দেহের সূচনা, চেতনার বিকাশ এবং অচেতনের অবিরাম উন্মোচন পর্যন্ত সবকিছুই পূর্বনির্ধারিত, অপরপক্ষে জীবনের অগ্রগতি সময়ের প্রেক্ষাপটে বিদ্যমান, যা হলো একটি কোষের বিন্যাস; ঠিক যেমন কার্বনের হীরায় রূপান্তর এখানে চাপ, স্থিতিশীলতা ও বিশুদ্ধতার এক রূপক, যা জীবনের গঠন ও বিবর্তনের সঙ্গে সম্পর্কিত; চিত্রের বৈপরীত্যপূর্ণ গতি এবং সংযুক্ত মুখের অভিব্যক্তি জীবনের সামঞ্জস্যের পরিবর্তন সত্ত্বেও একটি অন্তর্নিহিত ঐক্যের ইঙ্গিত দেয়; প্রকৃতির নিয়মে প্রতিটি রূপান্তর নতুন সম্ভাবনা সৃষ্টি করে, যা জীবনের ধারাবাহিক বিকাশের প্রতিচ্ছবি;",

  en: "continuous changes brought about by time; that is, everything from the formation of the womb and the seed of creation to the emergence of the body, the development of consciousness, and the continuous unfolding of the unconscious is predetermined, while the progression of life exists within the context of time, represented by the arrangement of a cell; just as carbon transforms into diamond, this process serves as a metaphor for pressure, stability, and purity, all of which are associated with the formation and evolution of life; the contrasting movement in the painting and the expressions of the interconnected faces suggest an underlying unity despite changes in life's harmony; according to the laws of nature, every transformation creates new possibilities, reflecting the continuous evolution of life;",

  hi: "सृष्टि के बीज से लेकर देह का आरंभ, चेतना का विकास तथा अचेतन का निरंतर उद्घाटन—ये सभी पूर्वनिर्धारित हैं, जबकि जीवन की प्रगति समय के संदर्भ में विद्यमान रहती है, जो एक कोशिका की संरचना का प्रतीक है; ठीक उसी प्रकार जैसे कार्बन हीरे में परिवर्तित होता है, यहाँ यह प्रक्रिया दबाव, स्थिरता और शुद्धता का रूपक है, जो जीवन की संरचना और विकास से संबंधित है; चित्र की विरोधाभासी गति और परस्पर जुड़े मुखों की अभिव्यक्ति जीवन के सामंजस्य में परिवर्तन के बावजूद अंतर्निहित एकता का संकेत देती है; प्रकृति के नियमों के अनुसार प्रत्येक रूपांतरण नई संभावनाओं को जन्म देता है, जो जीवन के निरंतर विकास का प्रतिबिंब है;",

  sa: "संरचनातः सृष्टेः बीजाच्च आरभ्य देहस्य उत्पत्तिः, चेतनायाः विकासः, अचेतनस्य च अविच्छिन्नः आविष्कारः—एतत् सर्वं पूर्वनिर्धारितम् अस्ति, अपरपक्षे जीवनस्य प्रगतिः कालस्य सन्दर्भे विद्यते, या एकस्य कोशस्य विन्यासं सूचयति; यथा कार्बनं हीरकरूपेण परिणमते, तथैव अत्र एषा प्रक्रिया दबावस्य, स्थिरतायाः, शुद्धतायाश्च रूपकम् अस्ति, या जीवनस्य संरचनया विकासेन च सम्बद्धा; चित्रस्य विरोधाभासपूर्णा गतिः परस्परसम्बद्धमुखानां च अभिव्यक्तिः जीवनस्य सामञ्जस्ये परिवर्तने सति अपि अन्तर्निहिताम् एकतां सूचयति; प्रकृतेः नियमानुसारं प्रत्येकं रूपान्तरणं नूतनाः सम्भावनाः जनयति, याः जीवनस्य अविच्छिन्नविकासस्य प्रतिबिम्बम् अस्ति;"
},

