descFull: {
  bn: "রূপের মধ্যেই একটি সূত্র রয়েছে, যেখানে বৃষ্টিচক্রের প্রত্যাবর্তন সৃষ্টির সূচনাকে পুনরুজ্জীবিত করে, যা পরম সত্তায় স্থিরীকৃত প্রকৃতির গর্ভে কাল ও স্থানের প্রতিচ্ছবি; তাই শূন্য থেকে নয় মাসের যাত্রায় দেহের গঠন, অনুভূতির সূচনা এবং অন্তর্নিহিত সংবেদনশীলতা ক্রমশ প্রকাশিত হয়; চিত্রের পুরুষ ও প্রকৃতির মুখাবয়ব, বৃত্তাকার প্রতীক ও জ্যামিতিক বিন্যাস গর্ভের অন্তর্নিহিত জগৎ এবং মনের সম্ভাবনাময় অবস্থাকে নির্দেশ করে; এখানে সময় শুধু একটি পরিমাপ নয়, বরং জীবনের রূপান্তর ও আত্মপ্রকাশের এক অবিচ্ছিন্ন পরিসর, যেখানে পরম সত্তার স্থির রশ্মিতে জীবনের প্রদীপের সংবেদনশীল অন্তর্গত অগ্নিশিখা অব্যাহত;",

  en: "space during gestation; that is, every form contains an underlying principle, where the return of the rain cycle renews the beginning of creation, reflecting time and space within the womb of nature, established in the Supreme Being; thus, throughout the nine-month journey from zero, the formation of the body, the emergence of feelings, and inherent sensitivity gradually unfold; the faces of Purusha and Prakriti, the circular symbols, and the geometric arrangements in the painting indicate the inner world of the womb and the mind's state of potentiality; here, time is not merely a measurement, but an uninterrupted realm of life's transformation and self-expression, where the inner, sensitive flame of life's lamp continues to burn in the steady rays of the Supreme Being;",

  hi: "प्रत्येक रूप के भीतर एक मूल सूत्र विद्यमान है, जहाँ वर्षाचक्र की पुनरावृत्ति सृष्टि के आरंभ को पुनर्जीवित करती है, जो परम सत्ता में प्रतिष्ठित प्रकृति के गर्भ में काल और स्थान का प्रतिबिंब है; इस प्रकार, शून्य से नौ महीनों की यात्रा में देह का निर्माण, अनुभूति का आरंभ और अंतर्निहित संवेदनशीलता क्रमशः प्रकट होती है; चित्र में पुरुष और प्रकृति के मुखाकृतियाँ, वृत्ताकार प्रतीक तथा ज्यामितीय विन्यास गर्भ के अंतर्निहित जगत और मन की संभावनापूर्ण अवस्था को दर्शाते हैं; यहाँ समय केवल एक माप नहीं, बल्कि जीवन के रूपांतरण और आत्म-अभिव्यक्ति का एक अविच्छिन्न विस्तार है, जहाँ परम सत्ता की स्थिर किरणों में जीवन के दीपक की संवेदनशील आंतरिक ज्वाला निरंतर प्रज्वलित रहती है;",

  sa: "रूपे एकः मूलसूत्रः अन्तर्निहितः अस्ति, यत्र वर्षाचक्रस्य पुनरावृत्तिः सृष्टेः आरम्भं पुनर्जीवयति, यत् परमसत्तायां प्रतिष्ठितायाः प्रकृतेः गर्भे कालस्य स्थानस्य च प्रतिबिम्बम् अस्ति; अतः शून्यतः नवमासपर्यन्तं यात्रायां देहस्य निर्माणं, अनुभूतेः आरम्भः, अन्तर्निहिता संवेदनशीलता च क्रमेण अभिव्यज्यन्ते; चित्रे पुरुषप्रकृत्योः मुखाकृतयः, वृत्ताकारप्रतीकानि, ज्यामितीयविन्यासाश्च गर्भस्य अन्तर्निहितं जगत् मनसः सम्भावनापूर्णां च अवस्थां निर्दिशन्ति; अत्र कालः केवलं मापनं न, अपि तु जीवनस्य रूपान्तरणस्य आत्माभिव्यक्तेश्च अविच्छिन्नं क्षेत्रम्, यत्र परमसत्तायाः स्थिररश्मिषु जीवनदीपस्य संवेदनशीला अन्तर्ज्वाला निरन्तरं प्रज्वलिता तिष्ठति;"
},

